import os, csv

def W(path, text):
    if os.path.exists(path):
        try:
            os.chmod(path, 0o644)
        except OSError:
            pass
    with open(path, "w", newline="") as f:
        f.write(text)

def T(rows):
    return "".join(",".join(r) + "\n" for r in rows)

paths = ["backbone_rmsd.csv", "ca_core_rmsd.csv", "mass_weighted_rmsd.csv", "resid_weighted_rmsd.csv"]
for p in paths:
    with open(p, newline="") as f:
        rows = list(csv.reader(f))
    hdr = rows[0]
    fi = hdr.index("frame"); ti = hdr.index("t_ps")
    changed = 0
    for r in rows[1:]:
        frame = int(float(r[fi]))
        new = "%.4f" % frame  # zero-based cumulative time: frame 0 -> 0 ps
        if r[ti] != new:
            changed += 1
        r[ti] = new
    assert changed > 90, (p, changed)
    W(p, T(rows))
print("time rewritten for 4 tables OK")

import os, csv

def W(path, text):
    if os.path.exists(path):
