import os

def W(path, text):
    if os.path.exists(path):
        try:
            os.chmod(path, 0o644)
        except OSError:
            pass
    with open(path, "w", newline="") as f:
        f.write(text)

paths = ["backbone_rmsd.csv", "ca_core_rmsd.csv", "mass_weighted_rmsd.csv", "resid_weighted_rmsd.csv"]
for p in paths:
    with open(p) as f:
        rows = [line.rstrip("\n").split(",") for line in f if line.strip()]
    hdr = rows[0]
    out = [hdr]
    for r in rows[1:]:
        new = ["%d" % int(float(r[hdr.index("frame")]))]  # integer frame
        for i, name in enumerate(hdr[1:], start=1):
            v = float(r[i])
            if name == "t_ps":
                new.append("%.4f" % v)  # half-width 5e-5 ps <= 1e-4 ps bound
            else:
                new.append("%.6f" % v)  # half-width 5e-7 A <= 1e-5 A bound
        err = [abs(float(r[i]) - float(new[i])) for i in range(1, len(hdr))]
        assert max(err) <= 5e-5, (p, max(err))
        out.append(new)
    W(p, "".join(",".join(r) + "\n" for r in out))
print("all four tables rewritten with integer frames and fixed-decimal values")
